/**
 * Signals in message SteeringFeedback.
 *
 * Measured steering angle + status bitfield. Broadcast: consumed by BOTH JETSON and CLUSTER - the cluster reuses this frame rather than duplicating the angle into a cluster-specific frame.
 *
 * All signal values are as on the CAN bus.
 */
struct robot_steering_feedback_t {
    /**
     * Measured steering angle from pot (+left, REP-103). Consumed by JETSON and rendered by CLUSTER.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    float steering_angle;

    /**
     * b0 AT_TARGET: the CLAMPED setpoint was reached. Because it refers to the clamped value, AT_TARGET together with OUT_OF_RANGE means the request exceeded travel, was clamped, and that limit was reached - so read AT_TARGET ONLY alongside OUT_OF_RANGE.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t at_target;

    /**
     * b1 POT_FAULT: steering pot reading implausible. CLUSTER should grey out the steering display when set.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t pot_fault;

    /**
     * b2 OUT_OF_RANGE: the requested angle exceeded the mechanical travel and was clamped.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t out_of_range;

    /**
     * b3 SATURATED: the servo command hit its pulse-width limit.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t saturated;
};

