/**
 * Signals in message ImuAccel.
 *
 * IMU accelerometer X/Y/Z with sequence counter. 1 LSB = 0.001 m/s^2.
 *
 * All signal values are as on the CAN bus.
 */
struct robot_imu_accel_t {
    /**
     * Accelerometer X (bytes 0-1)
     *
     * Range: -32768..32767 (-32.768..32.767 m/s^2)
     * Scale: 0.001
     * Offset: 0
     */
    int16_t accel_x;

    /**
     * Accelerometer Y (bytes 2-3)
     *
     * Range: -32768..32767 (-32.768..32.767 m/s^2)
     * Scale: 0.001
     * Offset: 0
     */
    int16_t accel_y;

    /**
     * Accelerometer Z (bytes 4-5)
     *
     * Range: -32768..32767 (-32.768..32.767 m/s^2)
     * Scale: 0.001
     * Offset: 0
     */
    int16_t accel_z;

    /**
     * Sample-cycle counter (byte 6). MUST equal ImuGyroFlags.sequence for the same sample - the Jetson rejects the whole read when they differ.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t sequence;

    /**
     * Reserved (byte 7), send 0
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t reserved;
};

/**
 * Signals in message ImuGyroFlags.
 *
 * IMU gyroscope X/Y/Z, IMU reset flag and sequence counter. 1 LSB = 0.001 rad/s.
 *
 * All signal values are as on the CAN bus.
 */
struct robot_imu_gyro_flags_t {
    /**
     * Gyroscope X (bytes 0-1)
     *
     * Range: -32768..32767 (-32.768..32.767 rad/s)
     * Scale: 0.001
     * Offset: 0
     */
    int16_t gyro_x;

    /**
     * Gyroscope Y (bytes 2-3)
     *
     * Range: -32768..32767 (-32.768..32.767 rad/s)
     * Scale: 0.001
     * Offset: 0
     */
    int16_t gyro_y;

    /**
     * Gyroscope Z (bytes 4-5). The TIVA pre-inverts this to the robot frame; the Jetson applies no host-side inversion.
     *
     * Range: -32768..32767 (-32.768..32.767 rad/s)
     * Scale: 0.001
     * Offset: 0
     */
    int16_t gyro_z;

    /**
     * 1 = the IMU was re-initialised/crashed and recovered (byte 6). The Jetson forces gyro Z to 0 and holds its existing calibration while this is set.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t imu_reset;

    /**
     * Sample-cycle counter (byte 7 - NOT byte 6 as in ImuAccel). MUST equal ImuAccel.sequence for the same sample.
     *
     * Range: 0..255 (0..255 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t sequence;
};

/**
 * Signals in message VehicleStatus.
 *
 * Instrument-cluster display status: vehicle speed + gear + trip distance (Tiva -> cluster)
 *
 * All signal values are as on the CAN bus.
 */
struct robot_vehicle_status_t {
    /**
     * Vehicle speed (converted from encoder rad/s on Tiva). Bytes 0-1, 1 LSB = 1 m/min. UNIT CHANGED 2026-08-05 from 0.1 km/h: this robot runs 0.7-2 m/s, which is 2-7 km/h (a display that looks parked) but 40-120 m/min. Whole m/min is deliberate - 1 m/min is 0.017 m/s, finer than the drive can hold, so tenths would only show noise. The signal range is the full uint16 span; the vehicle's real ceiling is far lower.
     *
     * Range: 0..65535 (0..65535 m/min)
     * Scale: 1
     * Offset: 0
     */
    uint16_t speed;

    /**
     * Gear/direction enum at BYTE 2 (moved from byte 1 when speed widened): 0=N, 1=D, 2=R, derived from encoder direction. No Park - this vehicle has no parking pawl.
     *
     * Range: 0..2 (0..2 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t gear;

    /**
     * TRIP distance in metres, bytes 3-4, 1 LSB = 1 m. Accumulated on the Tiva as TOTAL PATH LENGTH (the absolute value of each increment), so reversing ADDS distance like a real trip meter rather than subtracting. RESET-RELATIVE, NOT a lifetime ODO: it zeroes on every Tiva power-cycle/reset. SATURATES at 65535 m (65.5 km) rather than wrapping. A permanent ODO needs non-volatile storage on the Tiva and is deliberately NOT this signal. See `odo_m` in bytes 5-7, which IS that signal.
     *
     * Range: 0..65535 (0..65535 m)
     * Scale: 1
     * Offset: 0
     */
    uint16_t trip_m;

    /**
     * LIFETIME odometer in metres, bytes 5-7, 1 LSB = 1 m. 24-BIT ON PURPOSE: it must outlive trip_m's uint16 (65.5 km), which a permanent odometer passes quickly. 24 bits reaches 16 777 215 m = 16 777 km - decades for this robot - and fills 0x200's last three free bytes exactly, so no new frame and no new TX slot were needed. PERSISTENT: held in the Tiva's internal EEPROM, written every 10 m of travel, and RESTORED ON BOOT - it survives resets and power cycles. It is NOT zeroed by 0x140 ResetCommand (that zeroes trip_m only), and there is no way to clear it over CAN by design. SATURATES at the signal max rather than wrapping. Worst-case loss on a sudden power-off is one write interval, i.e. 10 m.
     *
     * Range: 0..16777215 (0..16777215 m)
     * Scale: 1
     * Offset: 0
     */
    uint32_t odo_m;
};

/**
 * Signals in message BatteryStatus.
 *
 * Battery/power status for the instrument cluster (Tiva->Cluster). Tiva plays the BMS role: computes SoC (coulomb counting + voltage re-anchor), power and range from the INA226. LAYOUT AND UNITS CHANGED 2026-08-05 (v2) - every signal moved; see the byte-budget note in build_dbc.py.
 *
 * All signal values are as on the CAN bus.
 */
struct robot_battery_status_t {
    /**
     * Bus voltage from the INA226. BYTE 0, 1 LSB = 0.1 V (NARROWED 2026-08-05 from uint16 x0.01 V to free a byte for the widened `range`). 0-25.5 V covers this 3S pack (9.0-12.6 V) with headroom. mV-precision voltage is not lost - it stays on the Tiva's UART heartbeat.
     *
     * Range: 0..255 (0..25.5 V)
     * Scale: 0.1
     * Offset: 0
     */
    uint8_t voltage;

    /**
     * Bus current from the INA226. BYTES 1-2 (MOVED from 2-3 2026-08-05), 1 LSB = 0.01 A - resolution deliberately UNCHANGED. SIGN CONVENTION: POSITIVE = DISCHARGE (current leaving the battery), NEGATIVE = CHARGE (current into the battery).
     *
     * Range: -32768..32767 (-327.68..327.67 A)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t current;

    /**
     * Battery state of charge. BYTE 3 (MOVED from byte 4 2026-08-05). Computed ON THE TIVA by coulomb counting re-anchored to an IR-compensated voltage->SoC LUT at rest (3S Li-ion, 9.0-12.6 V). The cluster renders this as-is. It is an ESTIMATE - accuracy is bounded by the provisional R_source.
     *
     * Range: 0..100 (0..100 %)
     * Scale: 1
     * Offset: 0
     */
    uint8_t soc;

    /**
     * Instantaneous power = voltage x current, computed on the Tiva. BYTES 4-5 (MOVED from 5-6), 1 LSB = 1 W. SCALE CHANGED 2026-08-05 from 0.1 kW: at 100 W/LSB this robot's entire 3-220 W range mapped to 0-2 counts, i.e. the signal was blind - confirmed on the wire in A3 step 4a, where 4.06 W transmitted as 0.0 kW. At 1 W/LSB the same range is 3-220 counts. THIS is the change that makes the POWER/REGEN strip move. Sign follows `current`: positive = discharge, negative = charge.
     *
     * Range: -32768..32767 (-32768..32767 W)
     * Scale: 1
     * Offset: 0
     */
    int16_t power;

    /**
     * Estimated remaining range, computed on the Tiva from remaining energy divided by recent consumption. BYTES 6-7, 1 LSB = 1 m (WIDENED 2026-08-05 from uint8 km - 255 km of headroom at 1 km resolution was useless on a robot whose display wants metres). CEILING: 65535 m = 65.5 km, and BATTERY_RANGE_MAX_KM was lowered from 255 to 65 to match, so a large estimate CLAMPS instead of silently wrapping to a plausible wrong number. 0 means NOT ESTIMABLE (stationary or charging), not 'empty'.
     *
     * Range: 0..65535 (0..65535 m)
     * Scale: 1
     * Offset: 0
     */
    uint16_t range;
};

